// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
// [slug, name, one-line definition, category, written in this locale (1) or English fallback (0)], sorted by name.
export const GLOSSARY_INDEX = Object.freeze({"locale":"pt-BR","terms":[["tokenized-stocks","Ações tokenizadas","Ações tokenizadas são tokens em blockchain que representam ações de empresas, como Apple ou Tesla, e buscam acompanhar o preço da ação, geralmente com uma ação real guardada por um custodiante como lastro.","tokenized-assets",1],["airdrop","Airdrop","Airdrop é a distribuição gratuita de tokens de um projeto para carteiras que cumprem certos critérios, como usar o protocolo antes de uma data ou ter um saldo de determinado ativo.","basics",1],["leverage","Alavancagem","Alavancagem é o uso de margem para abrir uma posição maior do que o seu capital, multiplicando tanto os ganhos quanto as perdas em relação ao valor depositado.","derivatives",1],["altcoin","Altcoin","Altcoin é qualquer criptomoeda que não seja o bitcoin, de grandes redes como Ethereum e Solana até tokens pequenos e memecoins.","basics",1],["aml","AML (prevenção à lavagem de dinheiro)","AML, sigla de anti-money laundering, é o conjunto de regras e controles que instituições financeiras e corretoras de cripto usam para prevenir e detectar lavagem de dinheiro e financiamento ao terrorismo.","regulation",1],["on-chain-analysis","Análise on-chain","Análise on-chain é o estudo dos dados públicos registrados em uma blockchain, como transações, saldos de carteiras e fluxos para corretoras, para entender o comportamento de investidores e da rede.","onchain",1],["apr-vs-apy","APR vs APY","APR é a taxa de rendimento anual simples, sem considerar juros sobre juros, enquanto APY é a taxa anual efetiva que já inclui a capitalização composta dos rendimentos ao longo do ano.","defi",1],["token-approval","Aprovação de token (allowance)","Aprovação de token (allowance) é a permissão que você dá, a partir da sua carteira, para um contrato inteligente gastar uma quantidade de determinado token em seu nome.","wallets-security",1],["arbitrage","Arbitragem","Arbitragem é a estratégia de lucrar com a diferença de preço do mesmo ativo em mercados diferentes, comprando onde está mais barato e vendendo onde está mais caro quase ao mesmo tempo.","trading",1],["funding-rate-arbitrage","Arbitragem de taxa de financiamento","Arbitragem de taxa de financiamento é a estratégia de comprar um ativo no spot e abrir um short do mesmo tamanho no perpétuo, ficando neutro ao preço e recebendo o funding quando ele é positivo.","derivatives",1],["real-world-assets","Ativos do mundo real (RWA)","Ativos do mundo real (RWA) são ativos tradicionais, como títulos públicos, crédito privado, imóveis, ouro ou ações, representados por tokens em blockchain para serem emitidos, negociados ou usados como garantia em cripto.","tokenized-assets",1],["two-factor-authentication","Autenticação de dois fatores (2FA)","A autenticação de dois fatores (2FA) é uma camada extra de segurança que exige, além da senha, um segundo código ou dispositivo para entrar na conta ou aprovar ações como saques.","wallets-security",1],["whale","Baleia (whale)","Baleia (whale) é como o mercado chama uma pessoa ou entidade que detém uma quantidade muito grande de uma criptomoeda, capaz de mexer no preço quando compra ou vende.","trading",1],["futures-basis","Base de futuros","Base de futuros é a diferença entre o preço de um contrato futuro e o preço à vista do mesmo ativo, normalmente expressa em valor ou em porcentagem anualizada.","derivatives",1],["bitcoin","Bitcoin (BTC)","Bitcoin (BTC) é a primeira criptomoeda, lançada em 2009, com oferta máxima de 21 milhões de unidades e uma rede descentralizada protegida por mineração (prova de trabalho).","basics",1],["blockchain","Blockchain","Blockchain é um registro digital compartilhado, organizado em blocos encadeados, que milhares de computadores mantêm juntos e que praticamente não pode ser alterado depois de gravado.","basics",1],["layer-1","Camada 1 (Layer 1, L1)","Camada 1 (L1) é uma blockchain base, como Bitcoin, Ethereum ou Solana, que processa e finaliza transações com seu próprio consenso e sua própria moeda nativa.","basics",1],["layer-2","Camada 2 (Layer 2, L2)","Camada 2 (L2) é uma rede construída sobre uma blockchain base, como o Ethereum, que processa transações fora dela de forma mais rápida e barata e depois registra os resultados na camada 1.","basics",1],["market-capitalization","Capitalização de mercado (market cap)","Capitalização de mercado é o valor total de uma criptomoeda, calculado multiplicando o preço atual pela oferta circulante de moedas.","basics",1],["custodial-wallet","Carteira custodial","Carteira custodial é uma carteira em que uma empresa, geralmente uma corretora, guarda as chaves privadas dos seus criptoativos e movimenta os fundos em seu nome.","wallets-security",1],["crypto-wallet","Carteira de criptomoedas","Carteira de criptomoedas é um aplicativo, dispositivo ou serviço que guarda as chaves privadas que dão acesso aos seus criptoativos e permite enviar, receber e assinar transações.","wallets-security",1],["hardware-wallet","Carteira de hardware (hardware wallet)","Uma carteira de hardware é um pequeno dispositivo físico que gera e guarda a chave privada offline e assina transações internamente, sem nunca expor a chave ao computador ou ao celular.","wallets-security",1],["cold-wallet","Carteira fria (cold wallet)","Uma carteira fria (cold wallet) é uma forma de guardar criptomoedas em que a chave privada fica em um ambiente sem conexão com a internet, como uma carteira de hardware ou um dispositivo offline.","wallets-security",1],["multisig-wallet","Carteira multisig","Uma carteira multisig é uma carteira que exige assinaturas de várias chaves diferentes, como 2 de 3, para aprovar uma transação, em vez de depender de uma única chave privada.","wallets-security",1],["non-custodial-wallet","Carteira não custodial (autocustódia)","Uma carteira não custodial é uma carteira de cripto em que só você controla a chave privada e a frase de recuperação, sem depender de uma corretora ou empresa para guardar ou liberar seus fundos.","wallets-security",1],["hot-wallet","Carteira quente (hot wallet)","Uma carteira quente (hot wallet) é qualquer carteira de cripto cujas chaves ficam em um dispositivo conectado à internet, como app de celular ou extensão de navegador, o que facilita o uso diário mas aumenta a exposição a ataques.","wallets-security",1],["cbdc","CBDC (moeda digital de banco central)","CBDC é a sigla em inglês para moeda digital de banco central: uma versão digital da moeda oficial de um país, emitida e garantida pelo próprio banco central, como o real ou o euro em formato digital.","stablecoins",1],["margin-call","Chamada de margem (margin call)","Chamada de margem (margin call) é o aviso de que a margem da sua posição ou conta está perto do mínimo exigido, sinalizando que você precisa adicionar fundos ou reduzir a posição para evitar liquidação.","derivatives",1],["private-key","Chave privada (private key)","A chave privada é um número secreto que prova que você é o dono de um endereço de cripto e permite assinar transações que movimentam os fundos daquele endereço.","wallets-security",1],["public-key","Chave pública (public key)","A chave pública é o número derivado da chave privada que permite à rede verificar suas assinaturas e do qual se gera o endereço da carteira, podendo ser compartilhada sem risco aos fundos.","wallets-security",1],["anti-phishing-code","Código antiphishing","O código antiphishing é uma palavra ou frase que você define na corretora e que passa a aparecer em todos os e-mails oficiais dela, ajudando a identificar mensagens falsas.","wallets-security",1],["referral-code","Código de indicação (desconto em taxas)","Um código de indicação é um código ou link usado no cadastro de uma corretora que associa sua conta a quem indicou e, conforme o programa, pode dar a você desconto nas taxas de negociação ou outros benefícios.","exchange-features",1],["coin-vs-token","Coin vs token (moeda e token)","Coin é a moeda nativa de uma blockchain própria, como BTC ou ETH, enquanto token é um ativo criado sobre uma blockchain existente por meio de um contrato inteligente.","basics",1],["block-confirmations","Confirmações de bloco","Confirmações de bloco são a quantidade de blocos adicionados à blockchain a partir do bloco que incluiu sua transação, e indicam o quanto ela está consolidada e difícil de reverter.","wallets-security",1],["demo-trading","Conta demo (demo trading)","Conta demo é um modo de negociação simulada em que você opera com saldo fictício, usando os mesmos gráficos e tipos de ordem da corretora, para aprender e testar estratégias sem arriscar dinheiro real.","exchange-features",1],["unified-trading-account","Conta unificada de negociação (UTA)","Uma conta unificada de negociação é um modelo de conta em que spot, margem, futuros e opções compartilham o mesmo saldo e a mesma margem, sem precisar transferir fundos entre carteiras separadas.","exchange-features",1],["futures-contract","Contrato futuro","Um contrato futuro é um acordo para comprar ou vender um ativo a um preço definido, com liquidação em uma data futura ou, no caso dos perpétuos, sem data de vencimento.","derivatives",1],["smart-contract","Contrato inteligente (smart contract)","Contrato inteligente é um programa publicado numa blockchain que executa automaticamente regras predefinidas, como trocar tokens ou liberar fundos, sem depender de um intermediário.","basics",1],["open-interest","Contratos em aberto (open interest)","Contratos em aberto (open interest) é o total de contratos futuros ou de opções que estão abertos e ainda não foram fechados ou liquidados em um determinado momento.","derivatives",1],["instant-convert","Converter (troca instantânea)","Converter é a função de troca instantânea das corretoras em que você escolhe duas moedas, vê uma cotação fixa por alguns segundos e troca uma pela outra com um clique, sem usar o livro de ofertas.","exchange-features",1],["copy-trading","Copy trading","Copy trading é um recurso em que você conecta parte do seu saldo a um trader escolhido e a plataforma replica automaticamente as operações dele na sua conta, de forma proporcional ao valor alocado.","exchange-features",1],["centralized-exchange","Corretora centralizada (CEX)","Corretora centralizada (CEX) é uma empresa que intermedeia a compra e venda de criptomoedas, guarda os ativos dos clientes e opera seu próprio livro de ofertas, como Binance, OKX, Bybit ou Mercado Bitcoin.","trading",1],["dex","Corretora descentralizada (DEX)","Uma corretora descentralizada (DEX) é uma plataforma onde você troca criptomoedas diretamente da sua carteira por meio de contratos inteligentes, sem entregar a custódia a uma empresa.","defi",1],["no-kyc-exchange","Corretora sem KYC","Uma corretora sem KYC é uma plataforma que permite negociar ou sacar criptoativos sem verificação de identidade, total ou até certo limite, em geral com restrições de produtos e de valores.","regulation",1],["cryptocurrency","Criptomoeda","Criptomoeda é um ativo digital que funciona sobre uma blockchain, usa criptografia para proteger as transferências e não depende de um banco central para existir.","basics",1],["dao","DAO (organização autônoma descentralizada)","Uma DAO (organização autônoma descentralizada) é uma organização em que as decisões são propostas e votadas pelos detentores de tokens e executadas por contratos inteligentes, em vez de uma diretoria tradicional.","defi",1],["defi","DeFi (finanças descentralizadas)","DeFi (finanças descentralizadas) é o conjunto de serviços financeiros, como trocas, empréstimos e rendimento, oferecidos por contratos inteligentes em blockchains, sem um banco ou corretora intermediando.","defi",1],["depeg","Depeg (perda de paridade)","Depeg é quando uma stablecoin ou outro token atrelado a um ativo se afasta do preço que deveria acompanhar, como uma moeda de 1 dólar sendo negociada a 0,97 ou a 1,03 dólar.","stablecoins",1],["auto-deleveraging","Desalavancagem automática (ADL)","Desalavancagem automática (ADL) é o mecanismo em que a corretora reduz ou fecha à força posições lucrativas de traders do lado oposto quando uma liquidação não pode ser coberta pelo mercado nem pelo fundo de seguro.","derivatives",1],["token-unlock","Desbloqueio de tokens (token unlock)","Desbloqueio de tokens é o momento em que tokens antes travados, em geral da equipe, de investidores ou da tesouraria, são liberados e passam a poder ser vendidos ou transferidos.","basics",1],["delisting","Deslistagem (delisting)","Deslistagem é quando uma corretora decide encerrar a negociação de um token ou de um par, retirando-o do mercado e, depois de um prazo, também encerrando depósitos e saques daquele ativo.","exchange-features",1],["position-sizing","Dimensionamento de posição","Dimensionamento de posição (position sizing) é decidir quanto colocar em cada operação com base em quanto você aceita perder se o stop loss for atingido.","trading",1],["synthetic-dollar","Dólar sintético (stablecoin delta neutra)","Um dólar sintético é um token que busca valer 1 dólar combinando uma posição comprada em cripto com uma posição vendida do mesmo tamanho em futuros perpétuos, de modo que as variações de preço se anulem.","stablecoins",1],["crypto-earn","Earn (produtos de rendimento em cripto)","Earn é o nome comum dos produtos de rendimento das corretoras, em que você deposita criptoativos por prazo flexível ou fixo e recebe juros ou recompensas, vindos de empréstimos, staking ou outras estratégias.","exchange-features",1],["defi-lending","Empréstimo DeFi (DeFi lending)","Empréstimo DeFi é o uso de protocolos em contratos inteligentes, como Aave e Compound, para emprestar cripto e receber juros ou tomar empréstimos deixando outra cripto como garantia.","defi",1],["wallet-address","Endereço de carteira (wallet address)","Um endereço de carteira é o identificador público, como 0x… no Ethereum ou bc1… no Bitcoin, que você informa para receber criptomoedas em uma rede específica.","wallets-security",1],["active-addresses","Endereços ativos","Endereços ativos são a quantidade de endereços únicos que enviaram ou receberam transações em uma blockchain dentro de um período, como um dia ou um mês, e servem como medida aproximada de uso da rede.","onchain",1],["address-poisoning","Envenenamento de endereço (address poisoning)","Envenenamento de endereço é um golpe em que o atacante envia uma transação de valor zero ou mínimo a partir de um endereço muito parecido com um que você usa, para que você copie o endereço errado do seu histórico.","wallets-security",1],["spot-bitcoin-etf","ETF de bitcoin à vista (spot)","Um ETF de bitcoin à vista é um fundo negociado em bolsa que compra e guarda bitcoin de verdade, permitindo que o investidor tenha exposição ao preço do BTC comprando cotas pela corretora de valores, sem lidar com carteiras.","regulation",1],["ethereum","Ethereum (ETH)","Ethereum é uma blockchain programável que executa contratos inteligentes, e o ether (ETH) é a criptomoeda nativa usada para pagar as taxas de gás e proteger a rede via staking.","basics",1],["block-explorer","Explorador de blocos (block explorer)","Um explorador de blocos é um site de busca que mostra os dados públicos de uma blockchain, permitindo consultar transações, endereços, blocos e saldos a partir de um hash ou de um endereço.","onchain",1],["flash-loan","Flash loan (empréstimo relâmpago)","Flash loan é um empréstimo sem garantia oferecido por protocolos DeFi que precisa ser tomado e devolvido dentro da mesma transação; se não for devolvido, a transação inteira é revertida como se nunca tivesse acontecido.","defi",1],["exchange-netflow","Fluxo de entrada e saída das corretoras (netflow)","O fluxo de entrada e saída das corretoras mede quanta cripto está sendo depositada e sacada das corretoras centralizadas, e o netflow é a diferença entre as entradas e as saídas num período.","onchain",1],["fomo","FOMO (medo de ficar de fora)","FOMO (fear of missing out, ou medo de ficar de fora) é a ansiedade de perder uma alta que leva o investidor a comprar por impulso, geralmente depois que o preço já subiu muito.","basics",1],["market-maker","Formador de mercado (market maker)","Um formador de mercado (market maker) é uma empresa ou trader que mantém ordens de compra e venda no livro o tempo todo, oferecendo liquidez e lucrando principalmente com o spread.","trading",1],["amm","Formador de mercado automatizado (AMM)","Um formador de mercado automatizado (AMM) é um contrato inteligente que define o preço de uma troca por uma fórmula matemática aplicada às reservas de um pool de liquidez, em vez de casar ordens de compradores e vendedores.","defi",1],["seed-phrase","Frase de recuperação (seed phrase)","A frase de recuperação (seed phrase) é uma sequência de 12 ou 24 palavras que dá acesso total a uma carteira de cripto e permite restaurá-la em qualquer aparelho, funcionando como a chave mestra de todas as suas contas nela.","wallets-security",1],["fud","FUD (medo, incerteza e dúvida)","FUD (fear, uncertainty and doubt, ou medo, incerteza e dúvida) é a disseminação de notícias negativas, boatos ou críticas sobre um ativo, verdadeiras ou não, que gera medo e venda por pânico.","basics",1],["insurance-fund","Fundo de seguro","Fundo de seguro é uma reserva mantida pela corretora de derivativos para cobrir perdas de posições liquidadas que fecham abaixo do preço de falência, evitando que o prejuízo recaia sobre outros traders.","derivatives",1],["coin-margined-futures","Futuros com margem em moeda (inversos)","Futuros com margem em moeda, ou inversos, são contratos em que a margem, o lucro e o prejuízo são calculados na própria criptomoeda, como BTC, e não em uma stablecoin.","derivatives",1],["usdt-margined-futures","Futuros com margem em USDT (lineares)","Futuros com margem em USDT, ou lineares, são contratos em que a margem, o lucro e o prejuízo são calculados em USDT, então o resultado cresce de forma linear com a variação do preço.","derivatives",1],["delivery-futures","Futuros com vencimento (trimestrais)","Futuros com vencimento (ou de entrega) são contratos que encerram em uma data fixa, como no fim de um trimestre, e são liquidados pelo preço de referência do ativo nesse momento.","derivatives",1],["perpetual-futures","Futuros perpétuos","Futuros perpétuos são contratos futuros sem data de vencimento, que acompanham o preço à vista do ativo por meio de uma taxa de financiamento paga periodicamente entre comprados e vendidos.","derivatives",1],["pig-butchering-scam","Golpe do abate de porcos (pig butchering)","O golpe do abate de porcos (pig butchering) é uma fraude de longo prazo em que o golpista cria uma relação de amizade ou romance online e depois convence a vítima a depositar cada vez mais em uma plataforma de investimento falsa.","wallets-security",1],["candlestick-chart","Gráfico de candles (candlestick)","Um gráfico de candles (candlestick) é um gráfico de preço em que cada vela mostra a abertura, a máxima, a mínima e o fechamento de um período, como 1 hora ou 1 dia.","trading",1],["bitcoin-halving","Halving do bitcoin","Halving do bitcoin é o evento, a cada 210.000 blocos (cerca de quatro anos), em que a recompensa dos mineradores por bloco é cortada pela metade, reduzindo a emissão de novos BTC.","basics",1],["transaction-hash","Hash da transação (TxID)","O hash da transação (TxID) é o código único que identifica uma transação na blockchain e permite consultá-la em um explorador de blocos para ver valor, endereços, rede e confirmações.","wallets-security",1],["hash-rate","Hash rate (taxa de hash)","Hash rate é o poder computacional total que os mineradores dedicam a uma rede de prova de trabalho, medido em cálculos de hash por segundo, como terahashes (TH/s) ou exahashes (EH/s).","onchain",1],["hedging","Hedge (proteção)","Hedge é abrir uma posição que ganha quando a sua posição principal perde, para reduzir o impacto de movimentos de preço contra você, em troca de abrir mão de parte do ganho.","derivatives",1],["hodl","HODL","HODL é a estratégia de comprar uma criptomoeda e mantê-la por longo prazo, sem vender nas quedas e oscilações, termo nascido de um erro de digitação de hold num fórum em 2013.","basics",1],["fear-and-greed-index","Índice de Medo e Ganância (Fear and Greed)","O Índice de Medo e Ganância é um indicador de sentimento que resume, numa escala de 0 a 100, se o mercado de cripto está dominado pelo medo (perto de 0) ou pela ganância (perto de 100).","onchain",1],["dual-investment","Investimento duplo (dual investment)","Investimento duplo é um produto estruturado de corretora em que você deposita uma cripto ou stablecoin, escolhe um preço-alvo e uma data, e no vencimento recebe juros mais o capital na moeda original ou na outra moeda, conforme o preço final.","exchange-features",1],["kyc","KYC (conheça seu cliente)","KYC, sigla de know your customer (conheça seu cliente), é o processo em que uma corretora ou instituição financeira confirma a identidade do usuário com documento, selfie e dados pessoais antes de liberar serviços.","regulation",1],["launchpad","Launchpad (venda de tokens)","Launchpad é uma plataforma, geralmente dentro de uma corretora, em que você pode comprar tokens de um projeto novo numa venda antes de ele ser listado para negociação aberta.","exchange-features",1],["launchpool","Launchpool","Launchpool é um produto de corretora em que você deixa tokens bloqueados ou em staking por alguns dias e recebe, em troca, uma parte dos tokens de um projeto novo que está para ser listado.","exchange-features",1],["liquidation","Liquidação","Liquidação é o fechamento forçado de uma posição alavancada pela corretora quando a margem restante cai abaixo da margem de manutenção, para evitar que as perdas ultrapassem a garantia.","derivatives",1],["liquidity","Liquidez","Liquidez é a facilidade de comprar ou vender um ativo rapidamente, em quantidade relevante, sem mexer muito no preço.","trading",1],["withdrawal-whitelist","Lista de endereços autorizados (whitelist de saque)","A whitelist de saque é um recurso da corretora que permite sacar cripto somente para endereços que você cadastrou e aprovou antes, bloqueando saques para qualquer endereço novo.","wallets-security",1],["token-listing","Listagem de token","Listagem de token é quando uma corretora passa a oferecer um criptoativo para depósito e negociação, abrindo pares como TOKEN/USDT no mercado à vista ou contratos de futuros sobre ele.","exchange-features",1],["order-book","Livro de ofertas (order book)","Livro de ofertas (order book) é a lista em tempo real de todas as ordens limitadas de compra e de venda de um par, organizadas por preço, que mostra a profundidade do mercado.","trading",1],["unrealized-pnl","Lucro/prejuízo não realizado (PnL não realizado)","Lucro ou prejuízo não realizado (PnL não realizado) é o resultado que uma posição aberta teria se fosse fechada agora, calculado pela diferença entre o preço de entrada e o preço atual de referência.","derivatives",1],["cross-margin","Margem cruzada","Margem cruzada é o modo em que todo o saldo disponível da conta de futuros serve de garantia para as posições abertas, afastando a liquidação mas colocando o saldo inteiro em risco.","derivatives",1],["maintenance-margin","Margem de manutenção","Margem de manutenção é o valor mínimo de margem que uma posição alavancada precisa manter; se o patrimônio da posição cair abaixo dele, a corretora inicia a liquidação.","derivatives",1],["portfolio-margin","Margem de portfólio","Margem de portfólio é um modo de cálculo em que a exigência de margem considera o risco líquido de todas as posições juntas, permitindo menos margem quando elas se compensam.","derivatives",1],["initial-margin","Margem inicial","Margem inicial é o valor mínimo que você precisa depositar como garantia para abrir uma posição alavancada, calculado como o valor da posição dividido pela alavancagem.","derivatives",1],["isolated-margin","Margem isolada","Margem isolada é o modo em que cada posição tem sua própria margem separada, de modo que uma liquidação só consome o valor alocado àquela posição e não o resto da conta.","derivatives",1],["all-time-high","Máxima histórica (ATH)","Máxima histórica (ATH, all-time high) é o maior preço que um ativo já atingiu desde que começou a ser negociado.","basics",1],["memecoin","Memecoin","Memecoin é uma criptomoeda inspirada em memes, piadas ou cultura da internet, cujo preço depende principalmente de comunidade, atenção e especulação, e não de um produto ou receita.","basics",1],["memo-tag","Memo / tag de destino","Memo ou tag de destino é um código extra, exigido em redes como XRP, Stellar, TON e algumas outras, que identifica a conta do destinatário quando vários clientes de uma corretora compartilham o mesmo endereço.","wallets-security",1],["mempool","Mempool","Mempool é a área de espera onde as transações enviadas, mas ainda não confirmadas, ficam guardadas pelos nós da rede até serem incluídas em um bloco por um minerador ou validador.","onchain",1],["spot-trading","Mercado à vista (spot)","Mercado à vista (spot) é a negociação em que você compra ou vende a criptomoeda de fato, com entrega imediata, e passa a ter o ativo no saldo, sem contratos nem alavancagem.","trading",1],["bull-market","Mercado de alta (bull market)","Mercado de alta (bull market) é um período prolongado em que os preços sobem de forma geral, com topos e fundos cada vez mais altos e otimismo crescente entre os investidores.","basics",1],["bear-market","Mercado de baixa (bear market)","Mercado de baixa (bear market) é um período prolongado de queda generalizada dos preços, geralmente 20% ou mais a partir do topo, com pessimismo, volume menor e saída de investidores.","basics",1],["mev","MEV (valor máximo extraível)","MEV (valor máximo extraível) é o lucro que quem organiza as transações de um bloco, ou bots que pagam por prioridade, consegue obter escolhendo a ordem, incluindo ou excluindo transações.","defi",1],["mica","MiCA (regulação europeia de criptoativos)","MiCA (Markets in Crypto-Assets) é o regulamento da União Europeia que cria regras únicas para emissores de stablecoins e outros criptoativos e para prestadoras de serviços de cripto (CASPs) em todo o bloco.","regulation",1],["mining","Mineração de criptomoedas","Mineração de criptomoedas é o processo em que computadores especializados validam transações e criam novos blocos numa rede de prova de trabalho, recebendo moedas novas e taxas como recompensa.","basics",1],["margin-trading","Negociação com margem","Negociação com margem é operar usando dinheiro ou moedas emprestadas pela corretora, com o seu saldo como garantia, para abrir posições maiores ou vender a descoberto.","derivatives",1],["nft","NFT (token não fungível)","Um NFT (token não fungível) é um token único registrado em uma blockchain que representa a posse de um item digital específico, como uma arte, um ingresso, um item de jogo ou um domínio.","defi",1],["vip-tier","Nível VIP de taxas","Nível VIP é a categoria de taxas de uma corretora definida pelo seu volume de negociação ou saldo de ativos: quanto maior o nível, menores as taxas maker e taker e maiores os limites e benefícios.","exchange-features",1],["node","Nó (node) da blockchain","Um nó (node) é um computador que roda o software de uma blockchain, guarda uma cópia dos dados da rede, verifica transações e blocos pelas regras do protocolo e repassa essas informações a outros nós.","onchain",1],["circulating-supply","Oferta circulante","Oferta circulante é a quantidade de unidades de uma criptomoeda que já está disponível e pode ser negociada no mercado, sem contar tokens bloqueados ou ainda não emitidos.","basics",1],["options","Opções de cripto","Opções de cripto são contratos que dão ao comprador o direito, mas não a obrigação, de comprar (call) ou vender (put) um ativo a um preço definido, o strike, até ou em uma data de vencimento.","derivatives",1],["oracle","Oráculo de blockchain","Um oráculo de blockchain é um serviço que leva dados de fora da blockchain, como o preço do ETH em dólares, para dentro de contratos inteligentes que precisam dessa informação para funcionar.","defi",1],["market-order","Ordem a mercado","Ordem a mercado é a instrução para comprar ou vender imediatamente pelo melhor preço disponível no livro de ofertas, priorizando a execução em vez do preço exato.","trading",1],["limit-order","Ordem limitada","Ordem limitada é a instrução para comprar ou vender apenas a um preço definido por você ou melhor, ficando registrada no livro de ofertas até ser executada ou cancelada.","trading",1],["oco-order","Ordem OCO (uma cancela a outra)","Ordem OCO (one-cancels-the-other) é um par de ordens ligadas, normalmente um take profit e um stop loss, em que a execução de uma cancela automaticamente a outra.","trading",1],["post-only-order","Ordem post-only (somente maker)","Ordem post-only é uma ordem limitada que só é aceita se entrar no livro de ofertas como maker; se fosse executar na hora como taker, a corretora a cancela ou ajusta.","trading",1],["reduce-only-order","Ordem somente redução (reduce-only)","Ordem somente redução (reduce-only) é uma opção de ordem em futuros que só pode diminuir ou fechar uma posição existente, nunca aumentá-la nem abrir uma posição no sentido contrário.","derivatives",1],["stop-limit-order","Ordem stop limitada (stop-limit)","Ordem stop limitada é uma ordem que, ao atingir um preço de disparo, coloca automaticamente uma ordem limitada no livro de ofertas com um preço limite definido por você.","trading",1],["tokenized-gold","Ouro tokenizado","Ouro tokenizado é um token em blockchain que representa a propriedade de uma quantidade de ouro físico guardado em cofre por um custodiante, normalmente 1 onça troy de ouro por token.","tokenized-assets",1],["p2p-trading","P2P (negociação entre pessoas)","P2P é a negociação de cripto diretamente entre usuários, em que um compra e outro vende, geralmente USDT, combinando pagamento em reais por Pix ou transferência, com a corretora segurando a cripto em garantia até a confirmação.","exchange-features",1],["trading-pair","Par de negociação","Par de negociação é a combinação de dois ativos negociados entre si numa corretora, como BTC/USDT ou ETH/BRL, em que o preço do primeiro é cotado na unidade do segundo.","trading",1],["impermanent-loss","Perda impermanente (impermanent loss)","Perda impermanente é a diferença entre o valor que você teria simplesmente segurando dois tokens e o valor da sua posição em um pool de liquidez depois que o preço entre eles muda.","defi",1],["perp-dex","Perp DEX (futuros perpétuos on-chain)","Uma perp DEX é uma corretora descentralizada de futuros perpétuos, em que você opera com alavancagem a partir da sua própria carteira, com margem e liquidações controladas por contratos ou por uma blockchain própria.","defi",1],["stock-perpetuals","Perpétuos de ações (stock perpetuals)","Perpétuos de ações são contratos de futuros perpétuos que acompanham o preço de ações ou índices, como Nvidia ou o S&P 500, liquidados em USDT ou USDC, permitindo operar comprado ou vendido com alavancagem sem possuir a ação.","tokenized-assets",1],["phishing","Phishing","Phishing é um golpe em que alguém se passa por uma empresa, corretora, carteira ou pessoa de confiança para fazer você entregar senha, código 2FA, frase de recuperação ou assinar uma transação maliciosa.","wallets-security",1],["cross-chain-bridge","Ponte entre blockchains (cross-chain bridge)","Uma ponte entre blockchains (bridge) é um protocolo que permite mover tokens ou mensagens de uma rede para outra, por exemplo do Ethereum para uma rede de camada 2 ou para Solana.","defi",1],["liquidity-pool","Pool de liquidez (liquidity pool)","Um pool de liquidez é um conjunto de tokens travados em um contrato inteligente que permite trocas em uma DEX, em que os depositantes, chamados provedores de liquidez, recebem parte das taxas.","defi",1],["long-and-short","Posição comprada e vendida (long e short)","Long e short são as duas direções de uma operação: long (comprado) lucra quando o preço sobe, e short (vendido) lucra quando o preço cai.","derivatives",1],["liquidation-price","Preço de liquidação","Preço de liquidação é o preço de marcação em que sua posição alavancada será fechada à força, porque a margem restante terá caído até o nível de manutenção.","derivatives",1],["mark-price","Preço de marcação","Preço de marcação é o preço de referência que a corretora usa para calcular lucro não realizado e liquidações em futuros, baseado no preço índice e não só no último negócio.","derivatives",1],["index-price","Preço índice","Preço índice é a média ponderada do preço à vista de um ativo em várias corretoras, usada como referência para o preço de marcação e a taxa de financiamento.","derivatives",1],["dollar-cost-averaging","Preço médio (DCA)","DCA (dollar-cost averaging) é a estratégia de comprar um valor fixo de um ativo em intervalos regulares, independentemente do preço, para diluir o custo médio ao longo do tempo.","trading",1],["proof-of-stake","Prova de participação (PoS)","Prova de participação (PoS) é o mecanismo de consenso em que validadores travam criptomoedas como garantia para confirmar blocos, ganhando recompensas e arriscando perder parte do valor se agirem mal.","basics",1],["proof-of-reserves","Prova de reservas (proof of reserves)","A prova de reservas (proof of reserves) é um método que uma corretora usa para demonstrar que mantém em carteiras próprias ativos suficientes para cobrir os saldos dos clientes.","wallets-security",1],["proof-of-work","Prova de trabalho (PoW)","Prova de trabalho (PoW) é o mecanismo de consenso em que mineradores gastam poder computacional e energia para resolver um desafio matemático e ganhar o direito de adicionar o próximo bloco.","basics",1],["token-burn","Queima de tokens (token burn)","Queima de tokens é a retirada permanente de tokens de circulação, enviando-os para um endereço do qual ninguém consegue movimentá-los, o que reduz a oferta.","basics",1],["fiat-on-ramp","Rampa de entrada fiat (on-ramp)","Uma rampa de entrada fiat (on-ramp) é qualquer forma de trocar dinheiro tradicional, como reais, por criptoativos, por exemplo depósito via Pix numa corretora, compra com cartão ou negociação P2P.","regulation",1],["blockchain-network","Rede de depósito (escolha da rede)","A rede de depósito é a blockchain específica, como Ethereum (ERC20), Tron (TRC20) ou Solana, pela qual uma criptomoeda é transferida, e precisa ser a mesma no envio e no recebimento para o dinheiro chegar.","wallets-security",1],["travel-rule","Regra de viagem (travel rule)","A travel rule (regra de viagem) é a exigência de que prestadores de serviços de cripto enviem e recebam dados de quem envia e de quem recebe junto com transferências de criptoativos entre eles.","regulation",1],["long-short-ratio","Relação long/short","Relação long/short é um indicador que compara quantas contas ou quanto volume de posições estão comprados versus vendidos em um contrato futuro, mostrando o posicionamento dos traders.","derivatives",1],["risk-reward-ratio","Relação risco-retorno","Relação risco-retorno é a comparação entre quanto você pode perder até o stop loss e quanto pode ganhar até o alvo de uma operação, como 1 para 3.","trading",1],["restaking","Restaking","Restaking é a reutilização de ETH em stake, ou de tokens de staking líquido, como garantia para proteger serviços adicionais além da rede principal, em troca de recompensas extras e de riscos extras de penalidade.","defi",1],["geo-restrictions","Restrições geográficas (regiões restritas)","Restrições geográficas são regras pelas quais uma corretora ou produto de cripto bloqueia ou limita usuários de determinados países ou regiões, normalmente por exigências de licença, sanções ou leis locais.","regulation",1],["grid-trading-bot","Robô de grid (grid trading bot)","Um robô de grid é uma ferramenta automática que distribui várias ordens de compra e venda em intervalos fixos dentro de uma faixa de preço, comprando nas quedas e vendendo nas altas para lucrar com a oscilação.","exchange-features",1],["rug-pull","Rug pull (puxada de tapete)","Rug pull é um golpe em que os criadores de um token ou projeto retiram de repente a liquidez ou os fundos dos investidores e abandonam o projeto, deixando o token praticamente sem valor.","wallets-security",1],["satoshi","Satoshi (sats)","Satoshi é a menor unidade do bitcoin: 1 BTC equivale a 100.000.000 satoshis, o que permite comprar e enviar frações muito pequenas de bitcoin.","basics",1],["short-squeeze","Short squeeze","Short squeeze é uma alta rápida de preço provocada pela recompra forçada de quem estava vendido, seja por stop loss ou liquidação, o que empurra o preço ainda mais para cima.","derivatives",1],["slippage","Slippage (derrapagem)","Slippage (derrapagem) é a diferença entre o preço que você esperava ao enviar uma ordem e o preço médio em que ela foi realmente executada.","trading",1],["bid-ask-spread","Spread (diferença entre compra e venda)","Spread é a diferença entre o melhor preço de compra (bid) e o melhor preço de venda (ask) no livro de ofertas de um par, e funciona como um custo implícito de operar.","trading",1],["stablecoin","Stablecoin (moeda estável)","Uma stablecoin é uma criptomoeda projetada para manter um valor estável, geralmente 1 dólar americano, por meio de reservas em moeda tradicional, garantia em cripto ou mecanismos de mercado.","stablecoins",1],["algorithmic-stablecoin","Stablecoin algorítmica","Uma stablecoin algorítmica é uma moeda que tenta manter o valor de 1 dólar por regras de código que expandem ou reduzem a oferta, em vez de depender de reservas completas em dinheiro ou em cripto.","stablecoins",1],["crypto-backed-stablecoin","Stablecoin lastreada em cripto","Uma stablecoin lastreada em cripto é uma moeda estável criada a partir de garantias em criptomoedas depositadas em contratos inteligentes, normalmente com mais valor em garantia do que em moedas emitidas.","stablecoins",1],["staking","Staking","Staking é o ato de bloquear criptomoedas em uma rede proof of stake, diretamente ou por meio de um serviço, para ajudar a validar blocos e receber recompensas pagas pela própria rede.","defi",1],["liquid-staking","Staking líquido (liquid staking)","Staking líquido é uma forma de fazer staking em que você recebe um token que representa a moeda em stake mais as recompensas, podendo usá-lo ou vendê-lo enquanto o valor original continua validando a rede.","defi",1],["stop-loss","Stop loss","Stop loss é uma ordem programada para vender, ou fechar uma posição, automaticamente quando o preço atinge um nível definido, limitando a perda de uma operação.","trading",1],["trailing-stop","Stop móvel (trailing stop)","Stop móvel (trailing stop) é uma ordem stop que acompanha o preço a uma distância fixa, em valor ou porcentagem, subindo junto com ele numa posição comprada e disparando quando o preço recua essa distância.","trading",1],["sub-account","Subconta (sub-account)","Uma subconta é uma conta vinculada à sua conta principal numa corretora, com saldo e posições separados, usada para isolar estratégias, robôs ou chaves de API sem precisar de outro cadastro KYC.","exchange-features",1],["support-and-resistance","Suporte e resistência","Suporte e resistência são faixas de preço onde o mercado já parou várias vezes: o suporte é onde a queda costuma encontrar compradores, e a resistência é onde a alta costuma encontrar vendedores.","trading",1],["take-profit","Take profit","Take profit é uma ordem programada para fechar uma posição automaticamente quando o preço atinge um alvo de lucro definido por você.","trading",1],["funding-rate","Taxa de financiamento (funding rate)","Taxa de financiamento (funding rate) é um pagamento periódico entre traders comprados e vendidos em futuros perpétuos, usado para manter o preço do contrato próximo do preço à vista.","derivatives",1],["gas-fee","Taxa de gás (gas fee)","Taxa de gás é o valor pago na moeda nativa de uma blockchain, como ETH no Ethereum, para que uma transação ou operação com contrato inteligente seja processada pela rede.","basics",1],["withdrawal-fee","Taxa de saque","Taxa de saque é o valor cobrado por uma corretora quando você retira criptoativos para outro endereço ou retira reais para sua conta bancária, normalmente um valor fixo em cada moeda e rede.","exchange-features",1],["maker-taker-fees","Taxas maker e taker","Taxas maker e taker são as duas tarifas que uma corretora cobra por negociação: a maker vale para ordens que ficam no livro de ofertas e adicionam liquidez, e a taker para ordens que executam na hora e retiram liquidez.","trading",1],["tokenized-treasuries","Títulos do Tesouro tokenizados","Títulos do Tesouro tokenizados são tokens que representam cotas de fundos ou carteiras de títulos públicos de curto prazo, geralmente do Tesouro americano, e repassam ao detentor o rendimento desses juros on-chain.","tokenized-assets",1],["governance-token","Token de governança","Um token de governança é um token que dá ao seu detentor direito de propor e votar mudanças em um protocolo ou DAO, como taxas, parâmetros de risco e uso da tesouraria.","defi",1],["wrapped-token","Token embrulhado (wrapped token)","Um token embrulhado (wrapped token) é um token que representa outro ativo na proporção de 1 para 1, permitindo usar esse ativo em uma rede ou padrão em que ele não existe de forma nativa.","defi",1],["tokenomics","Tokenomics","Tokenomics é o conjunto de regras econômicas de um token: oferta total, distribuição entre equipe e investidores, cronograma de liberação, utilidade e mecanismos como queima ou recompensas.","basics",1],["last-price","Último preço","Último preço é o preço do negócio mais recente executado no livro de ofertas de um par ou contrato, aquele que aparece em destaque na tela e forma o gráfico de candles.","derivatives",1],["usdc","USDC (USD Coin)","USDC (USD Coin) é uma stablecoin emitida pela Circle que busca valer 1 dólar americano por token, lastreada em reservas de dinheiro e títulos de curto prazo do Tesouro dos EUA.","stablecoins",1],["usdt","USDT (Tether)","USDT (Tether) é a maior stablecoin do mercado, emitida pela empresa Tether, que busca manter o valor de 1 dólar americano por token com base em reservas compostas principalmente por títulos do Tesouro dos EUA e outros ativos.","stablecoins",1],["time-in-force","Validade da ordem (GTC, IOC, FOK)","Validade da ordem (time in force) é a regra que define por quanto tempo uma ordem fica ativa e como ela lida com execução parcial, nas opções mais comuns GTC, IOC e FOK.","trading",1],["validator","Validador","Validador é um participante de uma rede de prova de participação que trava moedas como garantia e roda software para propor e confirmar blocos, recebendo recompensas por isso.","basics",1],["total-value-locked","Valor total bloqueado (TVL)","O valor total bloqueado (TVL) é a soma, em dólares, de todos os ativos depositados nos contratos de um protocolo DeFi ou de uma blockchain em determinado momento.","defi",1],["fully-diluted-valuation","Valor totalmente diluído (FDV)","FDV (valor totalmente diluído) é o valor que uma criptomoeda teria se toda a sua oferta máxima já estivesse em circulação, calculado como preço vezes oferta máxima ou total.","basics",1],["vasp","VASP (prestadora de serviços de ativos virtuais)","VASP, sigla em inglês para prestadora de serviços de ativos virtuais, é a empresa que troca, transfere, guarda ou administra criptoativos para clientes, como corretoras e custodiantes, e por isso fica sujeita a regras de registro e PLD.","regulation",1],["short-selling","Venda a descoberto (short selling)","Venda a descoberto (short selling) é vender um ativo que você não possui, por empréstimo ou por contrato futuro, para recomprá-lo depois mais barato e lucrar com a queda do preço.","derivatives",1],["volatility","Volatilidade","Volatilidade é a intensidade e a frequência com que o preço de um ativo sobe e desce num período; quanto maior, mais amplos e rápidos são os movimentos.","basics",1],["trading-volume","Volume de negociação","Volume de negociação é a quantidade total de um ativo comprada e vendida em um período, geralmente as últimas 24 horas, medida em moedas ou em dólares.","trading",1],["wash-trading","Wash trading","Wash trading é a prática de comprar e vender o mesmo ativo para si mesmo, ou entre contas combinadas, para criar volume falso e passar a impressão de um mercado ativo.","trading",1],["yield-farming","Yield farming (farming de rendimento)","Yield farming é a estratégia de mover cripto entre protocolos DeFi, como pools de liquidez e plataformas de empréstimo, para receber taxas e recompensas em tokens em troca de fornecer capital.","defi",1]]});
